export interface Token<T> { readonly key: symbol; readonly __type?: T }
export const token = <T>(description: string): Token<T> => ({ key: Symbol(description) });

const registry = new Map<symbol, unknown>();
export const register = <T>(t: Token<T>, value: T): void => { registry.set(t.key, value); };
export const resolve = <T>(t: Token<T>): T => {
  if (!registry.has(t.key)) throw new Error(`unregistered token: ${t.key.toString()}`);
  return registry.get(t.key) as T;
};
